using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

// --- Tool Definitions ---
var notes = new ResearchNotes();

[Description("Search the web for information on a query. Returns a list of relevant snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration purposes.
    // Replace with a real search API (e.g., Bing Search) for production use.
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    var results = query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") => """
            1. Quantum computers use qubits that can exist in superposition, enabling parallel computation.
            2. Google's Willow chip (2024) demonstrated quantum error correction below threshold.
            3. IBM plans to deliver 100,000-qubit systems by 2033.
            4. Key applications include cryptography, drug discovery, and optimization problems.
            5. Current limitations: decoherence, error rates, and extreme cooling requirements.
            """,
        var q when q.Contains("application") || q.Contains("use case") => """
            1. Pharmaceutical companies use quantum simulations to model molecular interactions.
            2. Financial institutions explore quantum algorithms for portfolio optimization.
            3. Logistics companies apply quantum annealing to route optimization.
            4. Quantum machine learning may accelerate pattern recognition tasks.
            """,
        var q when q.Contains("challenge") || q.Contains("limitation") => """
            1. Qubits are extremely fragile and susceptible to environmental noise.
            2. Current quantum computers require near absolute-zero temperatures.
            3. Quantum error correction overhead currently limits practical qubit counts.
            4. The "quantum advantage" threshold is still debated for most real-world tasks.
            """,
        _ => $"Search results for \"{query}\": General information found. The topic is active in current research."
    };
    return results;
}

[Description("Save a research note with a title and content for later summarization.")]
string TakeNote(
    [Description("Short title for the note")] string title,
    [Description("Content of the note")] string content)
{
    Console.WriteLine($"  [Tool] Taking note: \"{title}\"");
    notes.Add(title, content);
    return $"Note saved: \"{title}\" ({content.Length} chars)";
}

[Description("Retrieve all research notes taken so far.")]
string GetNotes()
{
    Console.WriteLine("  [Tool] Retrieving all notes...");
    return notes.GetAll();
}

// --- Build the AI Agent ---
var client = new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient();

var agent = new ChatClientBuilder(client)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Run the Research Loop ---
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic by:
        1. Performing multiple web searches to gather information from different angles.
        2. Taking notes on key findings as you go.
        3. After gathering enough information, retrieve your notes and produce a clear summary.

        Be systematic: search for overview, applications, and challenges/limitations.
        Always take notes before producing the final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("\nAgent is researching...\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('-', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('-', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('-', 50));
Console.WriteLine($"\nNotes collected: {notes.Count}");

// --- Helper Class ---
class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content) => _notes.Add((title, content));

    public string GetAll()
    {
        if (_notes.Count == 0) return "No notes taken yet.";
        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
    }
}

